// Investor is somebody the platform has onboarded.
//
// Every investor completes KYC/AML before joining the platform or taking part
// in any syndicate, and this is that record. The chain does not perform the
// checks and must not pretend to: it records that a named, accountable operator
// says they were performed, with a date and a reference somebody can be asked
// to produce.
//
// The record is what the deal token's transfer rule consults. That is the part
// worth being precise about: a token whose transfer is gated is not a bearer
// instrument, and an investor who buys one on a secondary market is buying into
// the same onboarding requirement as everyone else. If the gate lived only in
// the platform's user interface it would bind exactly nobody, because the token
// is a bank denomination and a bank send does not go through a user interface.
type Investor struct {
	Address string `protobuf:"bytes,1,opt,name=address,proto3" json:"address,omitempty"`
	// Who onboarded them. An operator group account, so the attestation is a
	// decision of an institution rather than of one employee.
	OnboardedBy string `protobuf:"bytes,2,opt,name=onboarded_by,json=onboardedBy,proto3" json:"onboarded_by,omitempty"`
	// The operator's own file reference for the KYC pack. Free text, and never
	// the documents themselves: a national identity number on a public chain is
	// a permanent disclosure that no later correction can withdraw.
	Reference string `protobuf:"bytes,3,opt,name=reference,proto3" json:"reference,omitempty"`
	// ISO 3166-1 alpha-2. The jurisdiction question is the one this platform
	// says out loud is unsettled, and holding the answer per investor is what
	// lets a later rule be applied without re-onboarding anybody.
	Jurisdiction string `protobuf:"bytes,4,opt,name=jurisdiction,proto3" json:"jurisdiction,omitempty"`
	// Struck off investors keep their record — they may still hold and still be
	// paid, because their money is already in a company and the chain has no
	// right to strand it — but they may not acquire more.
	Active      bool  `protobuf:"varint,5,opt,name=active,proto3" json:"active,omitempty"`
	OnboardedAt int64 `protobuf:"varint,6,opt,name=onboarded_at,json=onboardedAt,proto3" json:"onboarded_at,omitempty"`
}

